package in.smartcampus;
import jakarta.servlet.*;import jakarta.servlet.http.*;import jakarta.servlet.annotation.*;import java.io.*;import java.sql.*;
@WebServlet(urlPatterns={"/","/dashboard","/events","/bookings","/resources"})
public class PortalServlet extends HttpServlet {
 protected void doGet(HttpServletRequest q,HttpServletResponse r)throws IOException,ServletException {String p=q.getServletPath(); if(p.equals("/")){q.getRequestDispatcher("/index.jsp").forward(q,r);return;} HttpSession s=q.getSession(false);if(s==null||s.getAttribute("userId")==null){r.sendRedirect(q.getContextPath()+"/login?error=Please+sign+in+first");return;} String view=switch(p){case "/dashboard"->"/dashboard.jsp";case "/events"->"/events.jsp";case "/resources"->"/resources.jsp";default->"/bookings.jsp";}; try(Connection c=DB.get()){if(p.equals("/events")){q.setAttribute("events",c.createStatement().executeQuery("SELECT e.*, (SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.id) AS registered FROM events e WHERE e.event_date >= CURDATE() ORDER BY e.event_date"));} if(p.equals("/resources")){q.setAttribute("resources",c.createStatement().executeQuery("SELECT * FROM resources WHERE active=1 ORDER BY name"));} if(p.equals("/bookings")){PreparedStatement ps=c.prepareStatement("SELECT b.*,r.name AS resource_name FROM bookings b JOIN resources r ON b.resource_id=r.id WHERE b.user_id=? ORDER BY b.created_at DESC");ps.setInt(1,(Integer)s.getAttribute("userId"));q.setAttribute("bookings",ps.executeQuery());} if(p.equals("/resources")){q.setAttribute("resourceOptions",c.createStatement().executeQuery("SELECT * FROM resources WHERE active=1 ORDER BY name"));} if(p.equals("/dashboard")){PreparedStatement ps=c.prepareStatement("SELECT COUNT(*) FROM registrations WHERE user_id=?");ps.setInt(1,(Integer)s.getAttribute("userId"));ResultSet x=ps.executeQuery();x.next();q.setAttribute("eventCount",x.getInt(1));ps=c.prepareStatement("SELECT COUNT(*) FROM bookings WHERE user_id=? AND status='PENDING'");ps.setInt(1,(Integer)s.getAttribute("userId"));x=ps.executeQuery();x.next();q.setAttribute("pendingCount",x.getInt(1));q.setAttribute("eventPreview",c.createStatement().executeQuery("SELECT * FROM events WHERE event_date >= CURDATE() ORDER BY event_date LIMIT 3"));} q.getRequestDispatcher(view).forward(q,r); return;}catch(SQLException e){throw new ServletException(e);} }
}